1	package app
2	
3	import (
4		"log"
5		"time"
6	
7		tea "charm.land/bubbletea/v2"
8	
9		"github.com/anthnel/devdesk/internal/command"
10		"github.com/anthnel/devdesk/internal/config"
11		"github.com/anthnel/devdesk/internal/ui/components"
12		"github.com/anthnel/devdesk/internal/ui/configuration"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// themeDetectTimeout is how long app.theme: auto waits for the terminal's
17	// answer to the background query before settling on the dark theme. A variable
18	// so tests can shorten it.
19	var themeDetectTimeout = 500 * time.Millisecond
20	
21	// themeQueryDelay is how long a choice of auto made in session waits before the
22	// terminal is asked. A variable so tests can shorten it.
23	var themeQueryDelay = 100 * time.Millisecond
24	
25	// themeQueryDueMsg is the deferred background query coming due. gen ties it to
26	// the choice that deferred it: a newer choice of theme makes it stale.
27	type themeQueryDueMsg struct{ gen int }
28	
29	// themeDetectTimeoutMsg ends the wait for the terminal's answer. gen ties it to
30	// the wait that armed it: a newer choice of theme makes it stale.
31	type themeDetectTimeoutMsg struct{ gen int }
32	
33	// themeState is what the router knows about the theme in force and about the
34	// terminal-background detection behind app.theme: auto. Only Update() writes it
35	// (Rule 110); the Cmds it hands out carry copies of what they need.
36	type themeState struct {
37		// pending: the terminal was asked and neither answered nor timed out.
38		// View() leaves the terminal background alone meanwhile, so the terminal
39		// cannot answer with DevDesk's own colour.
40		pending bool
41		// gen counts theme choices; a timeout of an older one is ignored.
42		gen int
43		// answer is the first thing learned about the terminal, kept for the
44		// process: the terminal is asked at most once.
45		answer theme.Background
46		// resolution is the theme in force.
47		resolution theme.Resolution
48		// startInitDeferred: App.Init held back the start view's Init because the
49		// detection was pending at startup; settleTheme runs it, once. A choice of
50		// auto made in session never sets it, the view having been initialised.
51		startInitDeferred bool
52		// startWarns are the warnings the startup choice produced, posted by Init.
53		startWarns []string
54		// warned holds the candidate names already reported for the current choice,
55		// so the terminal's answer does not report one a second time.
56		warned map[string]bool
57	}
58	
59	// themeResolution returns the theme in force and why.
60	func (a *App) themeResolution() theme.Resolution { return a.theme.resolution }
61	
62	// themeFacts is what the configuration view shows about the theme in force:
63	// its name and, for auto, why it was chosen. A named theme has no reason.
64	func (a *App) themeFacts() configuration.ThemeFacts {
65		r := a.theme.resolution
66		facts := configuration.ThemeFacts{InUse: r.Name}
67		if r.Reason != "" {
68			facts.Reason = "auto: " + r.Reason
69		}
70		return facts
71	}
72	
73	// sendThemeFacts hands the resolution to the configuration view when the
74	// router holds one; a view built later reads themeFacts itself.
75	func (a *App) sendThemeFacts() {
76		view, ok := a.views[command.ViewConfiguration]
77		if !ok {
78			return
79		}
80		f := a.themeFacts()
81		// The view stores the facts and asks for nothing, so the Cmd is nil.
82		updated, _ := view.Update(configuration.ThemeFactsMsg(f))
83		a.setView(command.ViewConfiguration, updated)
84	}
85	
86	// themeDetectionPending reports whether the terminal's answer is awaited.
87	func (a *App) themeDetectionPending() bool { return a.theme.pending }
88	
89	// chooseTheme resolves app.theme, applies the palette and records the outcome.
90	// It returns the footer warnings, one per invalid candidate not reported yet
91	// (theme_dark and theme_light both count in auto, selected or not). fresh starts
92	// a new choice (startup, a save) and forgets what was reported before; the
93	// terminal's answer passes false. It is the single entry point for the startup
94	// choice, for a save from the configuration view and for the answer.
95	//
96	// "auto" with a known answer applies at once without asking again. "auto"
97	// without one starts from the dark theme and waits for the terminal: at startup
98	// themeInitCmd arms the query, in session themeQueryDueCmd defers it. A named
99	// theme cancels any wait.
100	func (a *App) chooseTheme(app config.AppConfig, fresh bool) []string {
101		type candidate struct{ name, warn string }
102		var r theme.Resolution
103		var candidates []candidate
104		if app.IsAutoTheme() {
105			if !a.theme.pending {
106				a.theme.gen++
107			}
108			bg := a.theme.answer
109			dark, light := app.EffectiveThemeDark(), app.EffectiveThemeLight()
110			r = theme.ResolveAuto(bg, dark, light)
111			a.theme.pending = bg == theme.BackgroundUnknown
112			selected, other, otherBg := dark, light, theme.BackgroundLight
113			if bg == theme.BackgroundLight {
114				selected, other, otherBg = light, dark, theme.BackgroundDark
115			}
116			candidates = []candidate{
117				{selected, r.Warning},
118				{other, theme.ResolveAuto(otherBg, dark, light).Warning},
119			}
120		} else {
121			a.theme.gen++
122			a.theme.pending = false
123			r = theme.ResolveNamed(app.Theme)
124			candidates = []candidate{{app.Theme, r.Warning}}
125		}
126		a.theme.resolution = r
127		theme.ApplyTheme(r.Theme)
128		theme.CurrentThemeName = r.Name
129		if r.Reason != "" {
130			log.Printf("INFO [theme] using %q (auto: %s)", r.Name, r.Reason)
131		} else {
132			log.Printf("INFO [theme] using %q (app.theme: %s)", r.Name, r.Requested)
133		}
134	
135		if fresh || a.theme.warned == nil {
136			a.theme.warned = map[string]bool{}
137		}
138		var warns []string
139		for _, c := range candidates {
140			if c.warn != "" && !a.theme.warned[c.name] {
141				a.theme.warned[c.name] = true
142				warns = append(warns, c.warn)
143			}
144		}
145		return warns
146	}
147	
148	// themeQueryDueCmd defers the background query by themeQueryDelay, so the frame
149	// that resets the terminal background (View leaves it nil while pending) is
150	// drawn first and the terminal answers with its own colour, not DevDesk's.
151	func (a *App) themeQueryDueCmd() tea.Cmd {
152		gen := a.theme.gen
153		return tea.Tick(themeQueryDelay, func(time.Time) tea.Msg { return themeQueryDueMsg{gen: gen} })
154	}
155	
156	// handleThemeQueryDue sends the deferred query and arms its timeout, unless the
157	// choice that deferred it is stale or already settled.
158	func (a *App) handleThemeQueryDue(msg themeQueryDueMsg) (tea.Model, tea.Cmd) {
159		if !a.theme.pending || msg.gen != a.theme.gen {
160			return a, nil
161		}
162		return a, a.themeQueryCmd()
163	}
164	
165	// themeQueryCmd is the background query and the timeout that ends its wait.
166	func (a *App) themeQueryCmd() tea.Cmd {
167		gen := a.theme.gen
168		return tea.Batch(
169			tea.RequestBackgroundColor,
170			tea.Tick(themeDetectTimeout, func(time.Time) tea.Msg { return themeDetectTimeoutMsg{gen: gen} }),
171		)
172	}
173	
174	// themeInitCmd is the theme part of Init: the one background query and its
175	// timeout when the answer is awaited, and the startup warning. Nil otherwise.
176	func (a *App) themeInitCmd() tea.Cmd {
177		var cmds []tea.Cmd
178		if a.theme.pending {
179			cmds = append(cmds, a.themeQueryCmd())
180		}
181		cmds = append(cmds, a.warnTheme(a.theme.startWarns))
182		return tea.Batch(cmds...)
183	}
184	
185	// handleBackgroundColor takes the terminal's answer. Only the first one while a
186	// query is pending counts; the router owns the message, no view sees it.
187	func (a *App) handleBackgroundColor(msg tea.BackgroundColorMsg) (tea.Model, tea.Cmd) {
188		if !a.theme.pending {
189			log.Printf("INFO [theme] ignoring a terminal background answer: none is awaited")
190			return a, nil
191		}
192		bg := theme.BackgroundNoAnswer
193		if msg.Color != nil {
194			bg = theme.BackgroundDark
