1	package app
2	
3	import (
4		"image/color"
5		"testing"
6	
7		tea "charm.land/bubbletea/v2"
8	
9		"github.com/anthnel/devdesk/internal/command"
10		"github.com/anthnel/devdesk/internal/ui/components"
11		"github.com/anthnel/devdesk/internal/ui/configuration"
12		"github.com/anthnel/devdesk/internal/ui/testutil"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14		"github.com/anthnel/devdesk/internal/ui/workspaces"
15	)
16	
17	// DEVDESK-258, review 2/2: the start view's Init and app.theme: auto.
18	//
19	// The start view is :workspaces (app.default_view), whose Init is quick and
20	// local (HOME is isolated) and yields exactly one workspaces.EntriesLoadedMsg
21	// per call: counting that message counts Init runs, with no test seam.
22	//
23	// Behavior these tests impose on the implementation:
24	//   - while the startup detection is pending, App.Init does not run the start
25	//     view's Init;
26	//   - settleTheme (terminal answer, dark or light, or timeout) runs it, once,
27	//     on the view that is current after rebuildViews when the theme changes;
28	//   - a late answer or a stale timeout after settling runs nothing more;
29	//   - without auto at startup, App.Init runs it as before and no answer
30	//     triggers another run;
31	//   - choosing auto in session (handleConfigSaved) never runs the Init of a
32	//     view that was already initialised, at save or at the answer.
33	
34	func workspacesAuto(t *testing.T, themeName string) *App {
35		t.Helper()
36		cfg := autoConfig(themeName, "", "")
37		cfg.App.DefaultView = "workspaces"
38		a := autoRouter(t, cfg)
39		if a.currentView != command.ViewWorkspaces {
40			t.Fatalf("setup: currentView = %q, want workspaces", a.currentView)
41		}
42		return a
43	}
44	
45	// appInit drains App.Init with the timers shortened.
46	func appInit(t *testing.T, a *App) []tea.Msg {
47		t.Helper()
48		testutil.FastTimers(t, &themeDetectTimeout)
49		testutil.FastTimers(t, &components.FooterMsgDuration)
50		return testutil.Msgs(a.Init())
51	}
52	
53	// startInits counts how many times the start view's Init ran in msgs.
54	func startInits(msgs []tea.Msg) int {
55		n := 0
56		for _, m := range msgs {
57			if _, ok := m.(workspaces.EntriesLoadedMsg); ok {
58				n++
59			}
60		}
61		return n
62	}
63	
64	func wantInits(t *testing.T, what string, msgs []tea.Msg, want int) {
65		t.Helper()
66		if got := startInits(msgs); got != want {
67			t.Errorf("%s: the start view's Init ran %d time(s), want %d", what, got, want)
68		}
69	}
70	
71	func updateMsgs(t *testing.T, a *App, msg tea.Msg) []tea.Msg {
72		t.Helper()
73		testutil.FastTimers(t, &components.FooterMsgDuration)
74		_, cmd := a.Update(msg)
75		return testutil.Msgs(cmd)
76	}
77	
78	// (a)
79	func TestAutoPendingInitDoesNotRunTheStartViewInit(t *testing.T) {
80		a := workspacesAuto(t, "auto")
81		msgs := appInit(t, a)
82		if _, ok := firstOf[themeDetectTimeoutMsg](msgs); !ok {
83			t.Fatal("setup: Init armed no detection timeout, auto is not pending")
84		}
85		wantInits(t, "App.Init while detection is pending", msgs, 0)
86	}
87	
88	// (b)
89	func TestALightAnswerRunsTheRebuiltViewsInitOnce(t *testing.T) {
90		a := workspacesAuto(t, "auto")
91		wantInits(t, "App.Init", appInit(t, a), 0)
92	
93		msgs := updateMsgs(t, a, tea.BackgroundColorMsg{Color: color.White})
94		if theme.CurrentThemeName != "github-light" {
95			t.Fatalf("CurrentThemeName = %q, want github-light", theme.CurrentThemeName)
96		}
97		wantInits(t, "light answer", msgs, 1)
98	
99		// The loading result reaches the view on screen, not a dropped one.
100		loaded, ok := firstOf[workspaces.EntriesLoadedMsg](msgs)
101		if !ok {
102			t.Fatal("no EntriesLoadedMsg to route")
103		}
104		// The Cmd was built after rebuildViews, so it belongs to the view now in
105		// a.views; routing its result must find that view.
106		if _, ok := a.views[a.currentView]; !ok {
107			t.Fatal("no current view to receive the loading result")
108		}
109		a.Update(loaded)
110	}
111	
112	// (c)
113	func TestADarkAnswerRunsTheStartViewInitOnce(t *testing.T) {
114		a := workspacesAuto(t, "auto")
115		wantInits(t, "App.Init", appInit(t, a), 0)
116	
117		msgs := updateMsgs(t, a, tea.BackgroundColorMsg{Color: color.Black})
118		wantInits(t, "dark answer", msgs, 1)
119	}
120	
121	// (d)
122	func TestATimeoutRunsTheStartViewInitOnce(t *testing.T) {
123		a := workspacesAuto(t, "auto")
124		init := appInit(t, a)
125		wantInits(t, "App.Init", init, 0)
126		timeout, ok := firstOf[themeDetectTimeoutMsg](init)
127		if !ok {
128			t.Fatal("Init armed no timeout")
129		}
130		wantInits(t, "timeout", updateMsgs(t, a, timeout), 1)
131	}
132	
133	// (e)
134	func TestNothingRunsTheStartViewInitTwice(t *testing.T) {
135		cases := []struct {
136			name  string
137			first func(timeout tea.Msg) tea.Msg
138			then  func(timeout tea.Msg) tea.Msg
139		}{
140			{"answer then timeout",
141				func(tea.Msg) tea.Msg { return tea.BackgroundColorMsg{Color: color.White} },
142				func(to tea.Msg) tea.Msg { return to }},
143			{"timeout then late answer",
144				func(to tea.Msg) tea.Msg { return to },
145				func(tea.Msg) tea.Msg { return tea.BackgroundColorMsg{Color: color.White} }},
146			{"answer then second answer",
147				func(tea.Msg) tea.Msg { return tea.BackgroundColorMsg{Color: color.Black} },
148				func(tea.Msg) tea.Msg { return tea.BackgroundColorMsg{Color: color.White} }},
149		}
150		for _, tc := range cases {
151			t.Run(tc.name, func(t *testing.T) {
152				a := workspacesAuto(t, "auto")
153				init := appInit(t, a)
154				timeout, ok := firstOf[themeDetectTimeoutMsg](init)
155				if !ok {
156					t.Fatal("Init armed no timeout")
157				}
158				wantInits(t, "first settle", updateMsgs(t, a, tc.first(timeout)), 1)
159				wantInits(t, "after settling", updateMsgs(t, a, tc.then(timeout)), 0)
160			})
161		}
162	}
163	
164	// (f)
165	func TestWithoutAutoInitRunsInAppInitAndNoAnswerRerunsIt(t *testing.T) {
166		for _, name := range []string{"", "default", "nord"} {
167			t.Run("app.theme="+name, func(t *testing.T) {
168				a := workspacesAuto(t, name)
169				wantInits(t, "App.Init", appInit(t, a), 1)
170				late := updateMsgs(t, a, tea.BackgroundColorMsg{Color: color.White})
171				wantInits(t, "an unsolicited answer", late, 0)
172			})
173		}
174	}
175	
176	// (g)
177	func TestChoosingAutoInSessionDoesNotReplayInit(t *testing.T) {
178		a := workspacesAuto(t, "nord")
179		wantInits(t, "App.Init", appInit(t, a), 1)
180		testutil.FastTimers(t, &themeQueryDelay)
181	
182		cfg := autoConfig("auto", "", "")
183		cfg.App.DefaultView = "workspaces"
184		save := updateMsgs(t, a, configuration.ConfigSavedMsg{Config: cfg, ThemeChanged: true})
185		wantInits(t, "the save", save, 0)
186	
187		due, ok := firstOf[themeQueryDueMsg](save)
188		if !ok {
189			t.Fatal("setup: the save deferred no terminal query")
190		}
191		wantInits(t, "the deferred query", updateMsgs(t, a, due), 0)
192		wantInits(t, "the answer", updateMsgs(t, a, tea.BackgroundColorMsg{Color: color.White}), 0)
193	}
