99	// theme cancels any wait.
100	func (a *App) chooseTheme(app config.AppConfig, fresh bool) []string {
101		type candidate struct{ name, warn string }
102		var r theme.Resolution
103		var candidates []candidate
104		if app.IsAutoTheme() {
105			if !a.theme.pending {
106				a.theme.gen++
107			}
108			bg := a.theme.answer
109			dark, light := app.EffectiveThemeDark(), app.EffectiveThemeLight()
110			r = theme.ResolveAuto(bg, dark, light)
111			a.theme.pending = bg == theme.BackgroundUnknown
112			selected, other, otherBg := dark, light, theme.BackgroundLight
113			if bg == theme.BackgroundLight {
114				selected, other, otherBg = light, dark, theme.BackgroundDark
115			}
116			candidates = []candidate{
117				{selected, r.Warning},
118				{other, theme.ResolveAuto(otherBg, dark, light).Warning},
119			}
120		} else {
121			a.theme.gen++
122			a.theme.pending = false
123			r = theme.ResolveNamed(app.Theme)
124			candidates = []candidate{{app.Theme, r.Warning}}
125		}
126		a.theme.resolution = r
127		theme.ApplyTheme(r.Theme)
128		theme.CurrentThemeName = r.Name
129		if r.Reason != "" {
130			log.Printf("INFO [theme] using %q (auto: %s)", r.Name, r.Reason)
131		} else {
132			log.Printf("INFO [theme] using %q (app.theme: %s)", r.Name, r.Requested)
133		}
134	
135		if fresh || a.theme.warned == nil {
136			a.theme.warned = map[string]bool{}
137		}
138		var warns []string
139		for _, c := range candidates {
140			if c.warn != "" && !a.theme.warned[c.name] {
141				a.theme.warned[c.name] = true
142				warns = append(warns, c.warn)
143			}
144		}
145		return warns
146	}
147	
148	// themeQueryDueCmd defers the background query by themeQueryDelay, so the frame
149	// that resets the terminal background (View leaves it nil while pending) is
150	// drawn first and the terminal answers with its own colour, not DevDesk's.
151	func (a *App) themeQueryDueCmd() tea.Cmd {
152		gen := a.theme.gen
153		return tea.Tick(themeQueryDelay, func(time.Time) tea.Msg { return themeQueryDueMsg{gen: gen} })
154	}
155	
156	// handleThemeQueryDue sends the deferred query and arms its timeout, unless the
157	// choice that deferred it is stale or already settled.
158	func (a *App) handleThemeQueryDue(msg themeQueryDueMsg) (tea.Model, tea.Cmd) {
159		if !a.theme.pending || msg.gen != a.theme.gen {
160			return a, nil
161		}
162		return a, a.themeQueryCmd()
163	}
164	
165	// themeQueryCmd is the background query and the timeout that ends its wait.
166	func (a *App) themeQueryCmd() tea.Cmd {
167		gen := a.theme.gen
168		return tea.Batch(
169			tea.RequestBackgroundColor,
170			tea.Tick(themeDetectTimeout, func(time.Time) tea.Msg { return themeDetectTimeoutMsg{gen: gen} }),
171		)
172	}
173	
174	// themeInitCmd is the theme part of Init: the one background query and its
175	// timeout when the answer is awaited, and the startup warning. Nil otherwise.
176	func (a *App) themeInitCmd() tea.Cmd {
177		var cmds []tea.Cmd
178		if a.theme.pending {
179			cmds = append(cmds, a.themeQueryCmd())
180		}
181		cmds = append(cmds, a.warnTheme(a.theme.startWarns))
182		return tea.Batch(cmds...)
183	}
184	
185	// handleBackgroundColor takes the terminal's answer. Only the first one while a
186	// query is pending counts; the router owns the message, no view sees it.
187	func (a *App) handleBackgroundColor(msg tea.BackgroundColorMsg) (tea.Model, tea.Cmd) {
188		if !a.theme.pending {
189			log.Printf("INFO [theme] ignoring a terminal background answer: none is awaited")
190			return a, nil
191		}
192		bg := theme.BackgroundNoAnswer
193		if msg.Color != nil {
194			bg = theme.BackgroundDark
195			if !msg.IsDark() {
196				bg = theme.BackgroundLight
197			}
198		}
199		return a, a.settleTheme(bg)
200	}
201	
202	// handleThemeDetectTimeout falls back to the dark theme, silently, when the wait
203	// it belongs to is still the current one.
204	func (a *App) handleThemeDetectTimeout(msg themeDetectTimeoutMsg) (tea.Model, tea.Cmd) {
205		if !a.theme.pending || msg.gen != a.theme.gen {
206			return a, nil
207		}
208		log.Printf("INFO [theme] no answer from the terminal after %v, using the dark theme", themeDetectTimeout)
209		return a, a.settleTheme(theme.BackgroundNoAnswer)
210	}
211	
212	// settleTheme records what the terminal said and applies the matching theme.
213	// The views are rebuilt when the effective theme changed: their styles were
214	// captured with the previous palette. The start view's deferred Init runs last.
215	func (a *App) settleTheme(bg theme.Background) tea.Cmd {
216		before := a.theme.resolution.Name
217		a.theme.answer = bg
218		a.theme.pending = false
219		cmds := []tea.Cmd{a.warnTheme(a.chooseTheme(a.config.App, false))}
220		if a.theme.resolution.Name != before {
221			cmds = append(cmds, a.rebuildViews())
222		}
223		cmds = append(cmds, a.runDeferredStartInit())
224		a.sendThemeFacts()
225		return tea.Batch(cmds...)
226	}
227	
228	// runDeferredStartInit returns the Init of the view on screen, once, when
229	// App.Init held it back. It reads a.views after any rebuild, so the Cmd belongs
230	// to the view that will receive its result.
231	func (a *App) runDeferredStartInit() tea.Cmd {
232		if !a.theme.startInitDeferred {
233			return nil
234		}
235		a.theme.startInitDeferred = false
236		if view, ok := a.views[a.currentView]; ok {
237			return view.Init()
238		}
239		return nil
240	}
241	
242	// warnTheme turns theme warnings into footer messages, nil when there are none.
243	func (a *App) warnTheme(texts []string) tea.Cmd {
244		var cmds []tea.Cmd
245		for _, t := range texts {
246			cmds = append(cmds, components.PostFooter(components.LevelWarning, t))
247		}
248		return tea.Batch(cmds...)
249	}
