// getFooterHeight returns the current footer height for the active view.
func (a *App) getFooterHeight() int {
	if view, ok := a.views[a.currentView]; ok {
		if fv, ok := view.(FooterView); ok {
			return fv.GetFooterHeight()
		}
	}
	return 0
}

// reinitializeViews drops every view so they are rebuilt against the current
// config, and returns the init cmd for the one on screen.
func (a *App) reinitializeViews() tea.Cmd {
	log.Printf("Reinitializing views with new config")
	a.views = make(map[command.ViewType]Screen)
	a.createView(a.currentView)

	var initCmd tea.Cmd
	if view, ok := a.views[a.currentView]; ok {
		initCmd = view.Init()
	}
	// The rebuilt view starts unaware of a blur that is still in effect.
	focusCmd := a.sendFocusTo(a.currentView, false)
	log.Printf("Views reinitialized successfully")
	return tea.Batch(initCmd, focusCmd)
}

// BlinkingView is implemented by a view with a row that blinks for a reason the
// registry does not know (an instant action, an agent running, children loading).
// The router asks the view on screen after every Update: a level, not an edge.
type BlinkingView interface {
	WantsBlink() bool
}

// Update is the router's only entry: the dispatch, then the level check of the
// animation chain. The view's own Cmd goes through untouched; ensureTick adds a
// Cmd only when a chain has to start or be replaced, and is idempotent, so a
// handler that already called it (jobsChanged) does not double the interval.
func (a *App) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	if _, ok := msg.(tea.FocusMsg); ok && !a.terminalBlurred {
		return a, nil // focus with no prior blur: nothing to do (DEVDESK-210)
// few are not:
//
//   - the theme is global process state, applied through theme.ApplyTheme;
//   - the secret backend decides which credentials.Storage the context holds,
//     which no view can rebuild itself into.
//
// The configuration view is deliberately kept rather than rebuilt: it is on
// screen, holds the cursor, and edits the very config object being handed back.
func (a *App) handleConfigSaved(msg configuration.ConfigSavedMsg) (tea.Model, tea.Cmd) {
	a.config = msg.Config
	// Cheap and idempotent, so no flag: every view is rebuilt below anyway.
	theme.SetGaugeGlyph(msg.Config.App.GaugeGlyph)

	var themeCmd tea.Cmd
	if msg.ThemeChanged {
		wasPending := a.theme.pending
		themeCmd = a.warnTheme(a.chooseTheme(msg.Config.App, true))
		if a.theme.pending && !wasPending {
			themeCmd = tea.Batch(themeCmd, a.themeQueryDueCmd())
		}
		a.sendThemeFacts()
	}
	if msg.BackendChanged {
		a.resolveSecretBackend()
	}
	if msg.EngineChanged {
		a.resolveContainerEngine()
	}
	if msg.ForgeChanged {
		a.closeForgeSession()
	}

	resizeCmd := a.rebuildViews()
	motionCmd := tea.Batch(a.applyMotion(msg.Config), a.applyWhenUnfocused(msg.Config))

	return a, tea.Batch(resizeCmd, a.syncProxyPortCmd(), a.redetectIfToolsMoved(msg.EngineChanged), motionCmd, themeCmd)
}

// rebuildViews drops every view except the configuration view so it is rebuilt
// against the saved config or the new palette on next use, recreates the one on
// screen and returns the resize that sizes it. Keeping the configuration view is
// what stops a save from throwing away the cursor after every keystroke. The
// recreated view's Init is not run, as in a save;
// settleTheme runs the start view's deferred Init itself.
func (a *App) rebuildViews() tea.Cmd {
	current := a.views[command.ViewConfiguration]
	a.views = make(map[command.ViewType]Screen)
	if current != nil {
		a.setView(command.ViewConfiguration, current)
	}
	a.createView(a.currentView)
